import manifest from "../../../assets/textures/terrain/micro-detail-atlas.json";
import type { AtlasMip } from "../baker/atlas-mips";
import { inflateWithDecompressionStream, parseKtx2Rgba8 } from "../baker/ktx2-rgba8";
import { MICRO_DETAIL_ATLAS_SIZE, MICRO_DETAIL_MIP_LEVELS, type MicroDetailAtlasManifest } from "./micro-detail";

/** Generated by `npm run micro-detail-atlas`: file hash, sizes and per-class statistics. */
export const MICRO_DETAIL_ATLAS = manifest as unknown as MicroDetailAtlasManifest;

const SOURCE = new URL("../../../assets/textures/terrain/micro-detail-atlas.ktx2", import.meta.url);

/** CPU copy of the baked atlas: level 0 is 576², followed by its explicit mips down to 36². */
export interface MicroDetailAtlas {
  levels: AtlasMip[];
  size: number;
}

export type MicroDetailFetch = (url: string, file: string) => Promise<ArrayBuffer>;

const fetchArrayBuffer: MicroDetailFetch = async url => {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Micro-detail atlas ${url}: HTTP ${response.status}`);
  return response.arrayBuffer();
};

/** Parses and checks a micro-detail KTX2 file against the layout (linear, 576², 5 levels). */
export const parseMicroDetailAtlas = async (bytes: ArrayBuffer | Uint8Array,
  inflate: (bytes: Uint8Array) => Promise<Uint8Array> = inflateWithDecompressionStream): Promise<MicroDetailAtlas> => {
  const texture = await parseKtx2Rgba8(bytes, inflate);
  const valid = !texture.srgb && texture.width === MICRO_DETAIL_ATLAS_SIZE &&
    texture.height === MICRO_DETAIL_ATLAS_SIZE && texture.levels.length === MICRO_DETAIL_MIP_LEVELS;
  if (valid) return { levels: texture.levels, size: texture.width };
  throw new Error(`Micro-detail atlas must be linear ${MICRO_DETAIL_ATLAS_SIZE}² with ${MICRO_DETAIL_MIP_LEVELS} levels`);
};

/**
 * Downloads (hashed Vite asset) and decodes the micro-detail atlas; worker-safe, no GPU work.
 * The renderer uploads it with `createAtlasTexture(levels[0].data, size, size, levels)`.
 */
export const loadMicroDetailAtlas = async (fetchBytes: MicroDetailFetch = fetchArrayBuffer) =>
  parseMicroDetailAtlas(await fetchBytes(SOURCE.href, MICRO_DETAIL_ATLAS.file.file));
